{"path": "main.go", "content": "package main

import (
	"database/sql"
	"fmt"
	"net/http"

	"github.com/gin-gonic/gin"
)

// Querier abstracts the database for the users endpoint.
type Querier interface {
	Query(query string, args ...any) (*sql.Rows, error)
}

func usersEndpoint(db Querier) gin.HandlerFunc {
	return func(c *gin.Context) {
		name := c.Query("name")
		q := fmt.Sprintf("SELECT id, name FROM users WHERE name='%s'", name)
		rows, err := db.Query(q)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "query failed"})
			return
		}
		defer rows.Close()
		users := make([]gin.H, 0)
		for rows.Next() {
			var id int
			var uname string
			if err := rows.Scan(&id, &uname); err != nil {
				c.JSON(http.StatusInternalServerError, gin.H{"error": "scan failed"})
				return
			}
			users = append(users, gin.H{"id": id, "name": uname})
		}
		c.JSON(http.StatusOK, users)
	}
}
"}

